from typing import Optional

import token_validator

from .models import User
from .exceptions import AuthenticationError
from .config import settings


def authenticate(token: str) -> Optional[User]:
    """Validate a bearer token and return the associated User, or raise.

    Uses token_validator.verify() which handles decoding, signature
    verification, and expiry checks internally.

    Raises:
        AuthenticationError: if the token is invalid, expired, or the
            associated user cannot be found.
    """
    try:
        claims: token_validator.Claims = token_validator.verify(
            token, settings.SECRET_KEY
        )
    except token_validator.InvalidTokenError as exc:
        raise AuthenticationError(str(exc)) from exc

    try:
        return User.get(claims.subject)
    except KeyError as exc:
        raise AuthenticationError(f"unknown user: {claims.subject}") from exc
